function parseIp(ip){var p=String(ip).trim().split('.');if(p.length!==4)return null;var o=[];for(var i=0;i<4;i++){var x=parseInt(p[i],10);if(isNaN(x)||x<0||x>255)return null;o.push(x);}return o;}
function toDecimal(o){return ((o[0]<<24)|(o[1]<<16)|(o[2]<<8)|o[3])>>>0;}
function intToIp(n){n=n>>>0;return [(n>>>24)&255,(n>>>16)&255,(n>>>8)&255,n&255];}
function vlsm(baseIp,basePrefix,reqs){
  var o=parseIp(baseIp);if(!o)return {error:'IP 非法'};
  basePrefix=+basePrefix;if(basePrefix<0||basePrefix>32)return {error:'前缀非法'};
  var baseMask=basePrefix===0?0:((0xFFFFFFFF<<(32-basePrefix))>>>0);
  var baseInt=(toDecimal(o)&baseMask)>>>0;var baseSize=Math.pow(2,32-basePrefix);
  var sorted=reqs.slice().sort(function(a,b){return b-a;});var alloc=[];var cur=baseInt;
  for(var i=0;i<sorted.length;i++){var h=sorted[i];var p;
    for(p=32;p>=0;p--){var cap=p>=31?(p===32?1:2):Math.pow(2,32-p)-2;if(cap>=h)break;}
    if(p<basePrefix)return {error:'需求 '+h+' 超过基础网络可划分粒度'};
    var size=Math.pow(2,32-p);if(cur+size>baseInt+baseSize)return {error:'地址空间不足，无法容纳全部需求'};
    var mask=((0xFFFFFFFF<<(32-p))>>>0);var cap2=p>=31?(p===32?1:2):Math.pow(2,32-p)-2;
    alloc.push({network:intToIp(cur).join('.'),prefix:p,mask:intToIp(mask).join('.'),capacity:cap2,usable:p>=31?cap2:cap2-2});
    cur+=size;}
  return {subnets:alloc};}
var EXPORTS={parseIp:parseIp,toDecimal:toDecimal,intToIp:intToIp,vlsm:vlsm};


